"use client";

import {
  type CSSProperties,
  type ElementType,
  type HTMLAttributes,
  type Ref,
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  type AnimationName,
  type AnimationOptions,
  type AnimationTrigger,
  animate,
  animationVars,
} from "../animation/presets";
import { useInView, useReducedMotion } from "../hooks";
import { cx } from "../utils/cx";

export type AnimateProps = AnimationOptions &
  Omit<HTMLAttributes<HTMLElement>, "children"> & {
    /** The preset to play. */
    animation: AnimationName;
    /** When it plays. `mount` (default), `view` (on scrolling into view), `hover`, `focus`, `click` or `manual`. */
    trigger?: AnimationTrigger;
    /** With `view`: play only the first time it enters the viewport. Default true. */
    once?: boolean;
    /** With `view`: how much must be visible, 0 to 1. Default 0.2. */
    threshold?: number;
    /** With `manual`: set to a new value (a number, or `true` after `false`) to play again. */
    play?: boolean | number;
    /** Position in a staggered list: delays by `index` steps. */
    index?: number;
    /** Called when the preset finishes. */
    onAnimationDone?: () => void;
    as?: ElementType;
    ref?: Ref<HTMLElement>;
    children?: React.ReactNode;
  };

/**
 * Plays an animation preset on its element, on mount or when a trigger fires:
 *
 *     <Animate animation="fade-up">Hello</Animate>
 *     <Animate animation="pop" trigger="view">Appears when scrolled to</Animate>
 *     <Animate animation="wiggle" trigger="hover" as="button">Hover me</Animate>
 *
 * It renders one element (`as`, a `div` by default). The presets are listed in `animations`. Reduced motion shows the
 * resting state.
 */
export function Animate({
  animation,
  trigger = "mount",
  once = true,
  threshold = 0.2,
  play,
  index,
  onAnimationDone,
  as: As = "div",
  duration,
  delay,
  easing,
  count,
  direction,
  distance,
  step,
  className,
  style,
  ref,
  onClick,
  ...rest
}: AnimateProps) {
  const el = useRef<HTMLElement | null>(null);
  const done = useRef(onAnimationDone);
  done.current = onAnimationDone;
  const vars = animationVars({ duration, delay, easing, count, direction, distance, step });
  const setRef = useCallback(
    (node: HTMLElement | null) => {
      el.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as { current: HTMLElement | null }).current = node;
    },
    [ref],
  );

  const restart = useCallback(() => {
    const node = el.current;
    if (!node) return;
    node.removeAttribute("data-hm-play");
    node.removeAttribute("data-hm-pending");
    void node.offsetWidth;
    node.setAttribute("data-hm-play", "");
  }, []);

  // view: hide an entrance before paint, then play when it scrolls into view
  useLayoutEffect(() => {
    const node = el.current;
    if (trigger !== "view" || !node) return;
    if (typeof IntersectionObserver === "undefined") return;
    node.setAttribute("data-hm-pending", "");
    const io = new IntersectionObserver(
      ([entry]) => {
        if (!entry) return;
        if (entry.isIntersecting) {
          restart();
          if (once) io.disconnect();
        } else if (!once) {
          node.removeAttribute("data-hm-play");
          node.setAttribute("data-hm-pending", "");
        }
      },
      { threshold },
    );
    io.observe(node);
    return () => {
      io.disconnect();
      node.removeAttribute("data-hm-pending");
    };
  }, [trigger, once, threshold, restart]);

  // manual: a changed `play` value plays it again
  const first = useRef(true);
  useEffect(() => {
    if (trigger !== "manual") return;
    if (first.current) {
      first.current = false;
      if (play === undefined || play === false) return;
    }
    if (play === false) return;
    restart();
  }, [trigger, play, restart]);

  useEffect(() => {
    const node = el.current;
    if (!node) return;
    const end = (e: AnimationEvent) => {
      if (e.target === node) done.current?.();
    };
    node.addEventListener("animationend", end);
    return () => node.removeEventListener("animationend", end);
  }, []);

  return (
    <As
      {...rest}
      ref={setRef}
      className={cx("hm-animate", className)}
      data-hm-anim={animation}
      data-hm-trigger={trigger === "mount" ? undefined : trigger}
      style={{ ...vars, ...(index !== undefined ? { "--hm-i": index } : null), ...style } as CSSProperties}
      onClick={(e: React.MouseEvent<HTMLElement>) => {
        onClick?.(e);
        if (trigger === "click") restart();
      }}
    />
  );
}

/**
 * Imperative animation: `const [ref, play] = useAnimate<HTMLButtonElement>()` then `play("shake")` (for example when a
 * form fails). `play` resolves when the animation ends.
 */
export function useAnimate<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const play = useCallback(
    (name: AnimationName, options?: AnimationOptions & { keep?: boolean }) =>
      ref.current ? animate(ref.current, name, options) : Promise.resolve(),
    [],
  );
  return [ref, play] as const;
}

export type CountUpProps = Omit<HTMLAttributes<HTMLSpanElement>, "children"> & {
  /** The number to count to. It counts from the previous value (from 0 on first show). */
  value: number;
  /** Milliseconds. Default 1200. */
  duration?: number;
  /** `Intl.NumberFormat` options, or a function that formats the number. */
  format?: Intl.NumberFormatOptions | ((n: number) => string);
  /** Locale for the formatting. */
  locale?: string;
  /** Count only once the number is in view. Default true. */
  whenInView?: boolean;
};

/**
 * A number that counts up (or down) to its value with an eased ramp. The final value is the accessible name. Reduced
 * motion shows the final value. The ramp writes the text directly and commits to React state once, at the end, so a
 * count is not a re-render per frame.
 */
export function CountUp({
  value,
  duration = 1200,
  format,
  locale,
  whenInView = true,
  className,
  ...rest
}: CountUpProps) {
  const reduced = useReducedMotion();
  const ref = useRef<HTMLSpanElement>(null);
  const text = useRef<HTMLSpanElement>(null);
  const from = useRef(0);
  const [shown, setShown] = useState(reduced ? value : 0);
  const [started, setStarted] = useState(!whenInView);
  const fmt = useCallback(
    (n: number) => (typeof format === "function" ? format(n) : new Intl.NumberFormat(locale, format).format(n)),
    [format, locale],
  );
  const format$ = useRef(fmt);
  format$.current = fmt;

  useEffect(() => {
    if (started) return;
    const node = ref.current;
    if (!node || typeof IntersectionObserver === "undefined") {
      setStarted(true);
      return;
    }
    const io = new IntersectionObserver(([e]) => {
      if (e?.isIntersecting) {
        setStarted(true);
        io.disconnect();
      }
    });
    io.observe(node);
    return () => io.disconnect();
  }, [started]);

  useEffect(() => {
    if (!started) return;
    if (reduced) {
      from.current = value;
      setShown(value);
      return;
    }
    const start = from.current;
    const t0 = performance.now();
    let raf = 0;
    const tick = (now: number) => {
      const p = Math.min(1, (now - t0) / duration);
      const eased = 1 - (1 - p) ** 4;
      const current = start + (value - start) * eased;
      from.current = current;
      // the last frame writes the exact value too: if it equals the state already, React will not render it
      if (text.current) text.current.textContent = format$.current(p < 1 ? current : value);
      if (p < 1) raf = requestAnimationFrame(tick);
      else setShown(value);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [value, duration, started, reduced]);

  return (
    <span {...rest} ref={ref} className={cx("hm-countup", className)}>
      <span className="hm-sr-only">{fmt(value)}</span>
      <span aria-hidden="true" ref={text}>
        {fmt(Math.abs(shown - value) < 0.5 && Number.isInteger(value) ? value : shown)}
      </span>
    </span>
  );
}

export type TypewriterProps = Omit<HTMLAttributes<HTMLSpanElement>, "children"> & {
  /** One string, or several to type and erase in turn. */
  text: string | string[];
  /** Milliseconds per character. Default 55. */
  speed?: number;
  /** Milliseconds to hold a finished string before erasing (with several strings or `loop`). Default 1400. */
  hold?: number;
  /** Start over after the last string. Default false for one string, true for several. */
  loop?: boolean;
  /** Show a blinking caret. Default true. */
  cursor?: boolean;
};

/**
 * Types text out a character at a time. The full text is the accessible name; reduced motion shows the first string.
 * It pauses while off screen and carries on from where it was when it comes back.
 */
export function Typewriter({
  text,
  speed = 55,
  hold = 1400,
  loop,
  cursor = true,
  className,
  ...rest
}: TypewriterProps) {
  const lines = Array.isArray(text) ? text : [text];
  const joined = lines.join("\n");
  const reduced = useReducedMotion();
  const [out, setOut] = useState(reduced ? (lines[0] ?? "") : "");
  const shouldLoop = loop ?? lines.length > 1;
  const ref = useRef<HTMLSpanElement>(null);
  const visible = useInView(ref, { threshold: 0 });
  // where the typing is, kept across pauses; a new text starts over
  const at = useRef({ joined, line: 0, n: 0, erasing: false });
  if (at.current.joined !== joined) at.current = { joined, line: 0, n: 0, erasing: false };

  // biome-ignore lint/correctness/useExhaustiveDependencies: `joined` stands for `lines`
  useEffect(() => {
    if (reduced) {
      setOut(lines[0] ?? "");
      return;
    }
    if (!visible) return;
    const s = at.current;
    let timer: ReturnType<typeof setTimeout>;
    const step = () => {
      const current = lines[s.line] ?? "";
      if (!s.erasing) {
        s.n += 1;
        setOut(current.slice(0, s.n));
        if (s.n >= current.length) {
          if (!shouldLoop && s.line === lines.length - 1) return;
          s.erasing = true;
          timer = setTimeout(step, hold);
          return;
        }
        timer = setTimeout(step, speed);
      } else {
        s.n -= 1;
        setOut(current.slice(0, Math.max(0, s.n)));
        if (s.n <= 0) {
          s.erasing = false;
          s.line = (s.line + 1) % lines.length;
          timer = setTimeout(step, speed * 4);
          return;
        }
        timer = setTimeout(step, speed / 2);
      }
    };
    const current = lines[s.line] ?? "";
    // finished and not looping: nothing left to schedule
    if (!s.erasing && s.n >= current.length && !shouldLoop && s.line === lines.length - 1) return;
    timer = setTimeout(step, s.erasing && s.n >= current.length ? hold : speed);
    return () => clearTimeout(timer);
  }, [joined, speed, hold, shouldLoop, reduced, visible]);

  return (
    <span {...rest} ref={ref} className={cx("hm-typewriter", className)}>
      <span className="hm-sr-only">{lines.join(". ")}</span>
      <span aria-hidden="true">{out}</span>
      {cursor ? <span className="hm-typewriter-caret" aria-hidden="true" /> : null}
    </span>
  );
}
